import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.CYjxsSA2.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),l={name:"faq.md"};function n(h,a,i,s,d,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="找不到扫描-项目数据" tabindex="-1">找不到扫描 / 项目数据 <a class="header-anchor" href="#找不到扫描-项目数据" aria-label="Permalink to &quot;找不到扫描 / 项目数据&quot;">​</a></h2><p>数据保存在<strong>数据目录</strong>（Windows 默认为程序所在目录，macOS 为系统的应用数据目录）。若把数据目录放到过其他位置，请到那里查找。</p><h2 id="启动提示「数据目录已被另一个进程占用」" tabindex="-1">启动提示「数据目录已被另一个进程占用」 <a class="header-anchor" href="#启动提示「数据目录已被另一个进程占用」" aria-label="Permalink to &quot;启动提示「数据目录已被另一个进程占用」&quot;">​</a></h2><p>同一份数据目录不能同时被两个实例打开。关掉已在运行的窗口后重试；确实需要同时开多份，请让每个实例各自使用一份独立的数据目录。</p><h2 id="数据库被锁定" tabindex="-1">数据库被锁定 <a class="header-anchor" href="#数据库被锁定" aria-label="Permalink to &quot;数据库被锁定&quot;">​</a></h2><p>确保没有其他 VAELOR 实例在运行。如果确实没有，重启程序即可解决。</p><h2 id="军团不调用工具" tabindex="-1">军团不调用工具 <a class="header-anchor" href="#军团不调用工具" aria-label="Permalink to &quot;军团不调用工具&quot;">​</a></h2><ul><li>确认所选模型支持函数调用（Tool Use）</li><li>确认角色的<strong>工具开关</strong>已启用</li><li>在系统配置里验证 Provider 连通性</li><li>若开了<strong>计划模式</strong>，主动扫描与利用类工具会被拒绝，这是预期行为</li></ul><h2 id="军团总在危险动作前弹确认" tabindex="-1">军团总在危险动作前弹确认 <a class="header-anchor" href="#军团总在危险动作前弹确认" aria-label="Permalink to &quot;军团总在危险动作前弹确认&quot;">​</a></h2><p>这是<strong>高危操作人工确认</strong>：破坏性命令、反弹 Shell、横向移动、远程批量执行会弹确认卡；普通 PoC 命令（<code>curl</code> / <code>wget</code> 探测）不会打扰。确认卡可勾选「批准并在本会话内自动批准」，超时未响应视为拒绝。</p><h2 id="权限被降档了-完全访问没被记住" tabindex="-1">权限被降档了 / 完全访问没被记住 <a class="header-anchor" href="#权限被降档了-完全访问没被记住" aria-label="Permalink to &quot;权限被降档了 / 完全访问没被记住&quot;">​</a></h2><p><strong>完全访问档不持久化</strong>：重开程序会回落为「工作区写入」，界面顶部有提示，点**「恢复完全访问」**即可改回（需二次确认）。</p><h2 id="命令报「必须隔离执行-但没有可用隔离环境」" tabindex="-1">命令报「必须隔离执行，但没有可用隔离环境」 <a class="header-anchor" href="#命令报「必须隔离执行-但没有可用隔离环境」" aria-label="Permalink to &quot;命令报「必须隔离执行，但没有可用隔离环境」&quot;">​</a></h2><p>执行隔离档位选了**「必须隔离」**，但 Docker 与 WSL 工具箱都没启用。二选一：启用工具箱，或把档位改为「优先隔离」/「不隔离」。</p><h2 id="报告里的证据写着来自历史运行" tabindex="-1">报告里的证据写着来自历史运行 <a class="header-anchor" href="#报告里的证据写着来自历史运行" aria-label="Permalink to &quot;报告里的证据写着来自历史运行&quot;">​</a></h2><p>这是有意的区分：只有属于<strong>本次运行</strong>的会话才计入本次战果。看到「本次运行未取得证据（证据来自历史运行）」，说明该条证据取自同项目更早的运行，需重新取证。</p><h2 id="漏洞管理里没有「漏洞报告」页签" tabindex="-1">漏洞管理里没有「漏洞报告」页签 <a class="header-anchor" href="#漏洞管理里没有「漏洞报告」页签" aria-label="Permalink to &quot;漏洞管理里没有「漏洞报告」页签&quot;">​</a></h2><p><strong>发现</strong>页签就是权威的漏洞账本：跨任务汇总、严重度分诊、证据内联；导出能力在<strong>侦察报告</strong>页签（按资产归集，Markdown / PDF）。</p><h2 id="想切换界面语言" tabindex="-1">想切换界面语言 <a class="header-anchor" href="#想切换界面语言" aria-label="Permalink to &quot;想切换界面语言&quot;">​</a></h2><p><strong>系统配置 → 外观与语言</strong>，可选简体中文 / English / 한국어。未手动选择时会自动跟随系统语言。</p><h2 id="ip-归属全部显示「未知」" tabindex="-1">IP 归属全部显示「未知」 <a class="header-anchor" href="#ip-归属全部显示「未知」" aria-label="Permalink to &quot;IP 归属全部显示「未知」&quot;">​</a></h2><p>缺少 IP 归属离线库。补上数据文件或用环境变量指定路径；缺库不影响其他字段。</p><h2 id="mcp-工具从军团工具表里消失了" tabindex="-1">MCP 工具从军团工具表里消失了 <a class="header-anchor" href="#mcp-工具从军团工具表里消失了" aria-label="Permalink to &quot;MCP 工具从军团工具表里消失了&quot;">​</a></h2><p>MCP Server 未启用或连不上时，该 Server 的<strong>整批工具会一并消失</strong>（不是逐个报错）。检查 Server 开关、本地进程是否存活，或远端地址是否可达。</p><h2 id="企业微信只收到部分消息-收不到" tabindex="-1">企业微信只收到部分消息 / 收不到 <a class="header-anchor" href="#企业微信只收到部分消息-收不到" aria-label="Permalink to &quot;企业微信只收到部分消息 / 收不到&quot;">​</a></h2><p>企业微信单条消息有长度上限，超出会被整条拒收，所以平台会把汇总拆成多条发送。收不到则检查「开关是否打开」与「推送阈值是否高于该漏洞级别」。</p><h2 id="配了代理但流量没走代理" tabindex="-1">配了代理但流量没走代理 <a class="header-anchor" href="#配了代理但流量没走代理" aria-label="Permalink to &quot;配了代理但流量没走代理&quot;">​</a></h2><p>启用条件是「开关打开 <strong>且</strong> 链上至少有一个节点」，两个条件缺一不可。详见<a href="/vaelor/advanced/proxy.html">代理与网络出口</a>。</p><h2 id="想要内网渗透能力" tabindex="-1">想要内网渗透能力 <a class="header-anchor" href="#想要内网渗透能力" aria-label="Permalink to &quot;想要内网渗透能力&quot;">​</a></h2><p>内网攻击依赖工具箱：优先推荐 <a href="/vaelor/advanced/docker.html">Kali Docker 工具箱</a>；无法安装 Docker 的 Windows 环境可使用 WSL 工具箱。</p><h2 id="更多排障" tabindex="-1">更多排障 <a class="header-anchor" href="#更多排障" aria-label="Permalink to &quot;更多排障&quot;">​</a></h2><p>各项限制与静默降级清单见<a href="/vaelor/advanced/troubleshooting.html">排障手册</a>。</p>',33)])])}const q=e(l,[["render",n]]);export{u as __pageData,q as default};
